import { extend } from 'flarum/extend';
import app from 'flarum/app';
import PermissionGrid from 'flarum/components/PermissionGrid';
import LiveChatAdminPage from './components/LiveChatAdminPage';

const ADMIN_DASHBOARD_SETTING = 'flatrate-live-chat.admin_dashboard_enabled';

function enabled(value) {
    return value === true || value === 1 || value === '1' || value === 'true';
}

app.initializers.add('flatrate-live-chat', (app) => {
    app.extensionData
        .for('flatrate-live-chat')
        .registerSetting({
            setting: ADMIN_DASHBOARD_SETTING,
            label: 'Enable Live Chat Rooms monitoring dashboard',
            help: 'Adds a private, read-only room monitoring page for administrators. Default: off.',
            type: 'boolean',
            default: false,
        })
        .registerSetting({
            setting: 'flatrate-live-chat.settings.charlimit',
            label: app.translator.trans('flatrate-live-chat.admin.settings.charlimit'),
            type: 'number',
        })
        .registerSetting({
            setting: 'flatrate-live-chat.settings.floodgate.number',
            label: app.translator.trans('flatrate-live-chat.admin.settings.floodgate.number'),
            type: 'number',
        })
        .registerSetting({
            setting: 'flatrate-live-chat.settings.floodgate.time',
            label: app.translator.trans('flatrate-live-chat.admin.settings.floodgate.time'),
            type: 'text',
        })
        .registerSetting({
            setting: 'flatrate-live-chat.settings.display.minimize',
            label: app.translator.trans('flatrate-live-chat.admin.settings.display.minimize'),
            type: 'switch',
        })
        .registerSetting({
            setting: 'flatrate-live-chat.settings.display.censor',
            label: app.translator.trans('flatrate-live-chat.admin.settings.display.censor'),
            type: 'switch',
        })
        .registerSetting({
            setting: 'flatrate-live-chat.live_chats_navigation_enabled',
            label: app.translator.trans('flatrate-live-chat.admin.settings.live_chats_navigation'),
            type: 'boolean',
            default: false,
        })
        .registerSetting({
            setting: 'flatrate-live-chat.general_live_enabled',
            label: app.translator.trans('flatrate-live-chat.admin.settings.general_live_enabled'),
            help: app.translator.trans('flatrate-live-chat.admin.settings.general_live_enabled_help'),
            type: 'boolean',
            // Migration-safe: unset DB value is treated as enabled server-side.
            default: true,
        })
        .registerSetting({
            setting: 'flatrate-live-chat.general_live_admin_preview_enabled',
            label: app.translator.trans('flatrate-live-chat.admin.settings.general_live_admin_preview_enabled'),
            help: app.translator.trans('flatrate-live-chat.admin.settings.general_live_admin_preview_enabled_help'),
            type: 'boolean',
            default: false,
        })
        .registerSetting({
            setting: 'flatrate-live-chat.general_live_user_enabled',
            label: app.translator.trans('flatrate-live-chat.admin.settings.general_live_user_enabled'),
            help: app.translator.trans('flatrate-live-chat.admin.settings.general_live_user_enabled_help'),
            type: 'boolean',
            default: false,
        })
        .registerSetting({
            setting: 'flatrate-live-chat.member_beta_enabled',
            label: app.translator.trans('flatrate-live-chat.admin.settings.member_beta_enabled'),
            help: app.translator.trans('flatrate-live-chat.admin.settings.member_beta_enabled_help'),
            type: 'boolean',
            default: false,
        })
        .registerPermission(
            {
                icon: 'fas fa-eye',
                label: app.translator.trans('flatrate-live-chat.admin.permissions.enabled'),
                permission: 'flatrate-live-chat.permissions.enabled',
                allowGuest: true,
            },
            'view'
        )
        .registerPermission(
            {
                icon: 'fas fa-comment-medical',
                label: app.translator.trans('flatrate-live-chat.admin.permissions.create.chat'),
                permission: 'flatrate-live-chat.permissions.create',
            },
            'start'
        )
        .registerPermission(
            {
                icon: 'fas fa-comment-medical',
                label: app.translator.trans('flatrate-live-chat.admin.permissions.create.channel'),
                permission: 'flatrate-live-chat.permissions.create.channel',
            },
            'start'
        )
        .registerPermission(
            {
                icon: 'fas fa-comments',
                label: app.translator.trans('flatrate-live-chat.admin.permissions.post'),
                permission: 'flatrate-live-chat.permissions.chat',
            },
            'reply'
        )
        .registerPermission(
            {
                icon: 'fas fa-pencil-alt',
                label: app.translator.trans('flatrate-live-chat.admin.permissions.edit'),
                permission: 'flatrate-live-chat.permissions.edit',
            },
            'reply'
        )
        .registerPermission(
            {
                icon: 'far fa-trash-alt',
                label: app.translator.trans('flatrate-live-chat.admin.permissions.delete'),
                permission: 'flatrate-live-chat.permissions.delete',
            },
            'reply'
        )
        .registerPermission(
            {
                icon: 'fas fa-eye',
                label: app.translator.trans('flatrate-live-chat.admin.permissions.moderate.vision'),
                permission: 'flatrate-live-chat.permissions.moderate.vision',
            },
            'moderate'
        )
        .registerPermission(
            {
                icon: 'far fa-trash-alt',
                label: app.translator.trans('flatrate-live-chat.admin.permissions.moderate.delete'),
                permission: 'flatrate-live-chat.permissions.moderate.delete',
            },
            'moderate'
        );

    if (enabled(app.data.settings[ADMIN_DASHBOARD_SETTING])) {
        app.extensionData.for('flatrate-live-chat').registerPage(LiveChatAdminPage);
    }
});
